import type { Algorithm, MedDose } from "./types";

/* Shared med chips ------------------------------------------------ */

const EPI: MedDose = {
  name: "Epinephrine",
  dose: "1 mg IV/IO — repeat every 3–5 min",
  counter: "epi",
  detail:
    "1 mg (10 mL of 0.1 mg/mL) IV/IO push, flush with 20 mL. Repeat every 3–5 minutes. " +
    "For nonshockable rhythms give as soon as feasible — earlier epinephrine in asystole/PEA " +
    "is associated with improved ROSC and survival. Follow each peripheral dose with a fluid flush and elevate the limb.",
};

const AMIO: MedDose = {
  name: "Amiodarone",
  dose: "300 mg IV/IO bolus → 2nd dose 150 mg",
  counter: "amio",
  detail:
    "First dose 300 mg IV/IO bolus (diluted in 20–30 mL D5W). Second dose 150 mg after 3–5 min if VF/pVT persists. " +
    "For shock-refractory VF/pVT after the 3rd shock. Do not combine with lidocaine — choose one agent.",
};

const LIDO: MedDose = {
  name: "Lidocaine",
  dose: "1–1.5 mg/kg → 2nd dose 0.5–0.75 mg/kg",
  counter: "lido",
  detail:
    "First dose 1–1.5 mg/kg IV/IO. Second dose 0.5–0.75 mg/kg after 5–10 min (maximum cumulative 3 mg/kg). " +
    "Alternative to amiodarone for shock-refractory VF/pVT.",
};

const MAG: MedDose = {
  name: "Magnesium",
  dose: "1–2 g IV/IO (torsades)",
  counter: "mag",
  detail:
    "1–2 g IV/IO diluted in 10 mL D5W over 5–20 min — only for torsades de pointes with prolonged QT. " +
    "Not recommended routinely in cardiac arrest.",
};

const ATROPINE: MedDose = {
  name: "Atropine",
  dose: "1 mg IV — repeat q3–5 min, max 3 mg",
  counter: "atropine",
  detail:
    "1 mg IV bolus, may repeat every 3–5 minutes to a maximum total of 3 mg. " +
    "Likely ineffective in high-grade (Mobitz II / third-degree) block with wide QRS — move to pacing/chronotropes early. " +
    "Avoid relying on atropine in cardiac transplant patients (denervated heart).",
};

const DOPAMINE: MedDose = {
  name: "Dopamine gtt",
  dose: "5–20 mcg/kg/min, titrate",
  detail: "Infusion 5–20 mcg/kg/min IV; titrate to heart rate and blood pressure. Taper slowly.",
};

const EPI_GTT: MedDose = {
  name: "Epinephrine gtt",
  dose: "2–10 mcg/min, titrate",
  detail: "Infusion 2–10 mcg/min IV; titrate to patient response. Bridge to pacing when available.",
};

const ADENOSINE: MedDose = {
  name: "Adenosine",
  dose: "6 mg rapid IV push → 12 mg",
  counter: "adenosine",
  detail:
    "First dose 6 mg rapid IV push via large (antecubital) vein followed by immediate 20 mL NS flush; " +
    "second dose 12 mg if required. Use only for regular rhythms (narrow, or wide AND regular + monomorphic). " +
    "Warn the patient about transient chest pressure / impending-doom sensation.",
};

